-- Lesson content rewrite: c_nicet
-- New slide format (terms at a glance, examples, comparisons, diagrams,
-- practice questions). Title slides kept; mini-exam questions untouched.
-- Safe to re-run: the current content is backed up once first.

create table if not exists lesson_content_backup (
  lesson_id uuid not null, content_blocks jsonb not null,
  backed_up_at timestamptz not null default now(), note text);
alter table lesson_content_backup enable row level security;

insert into lesson_content_backup (lesson_id, content_blocks, note)
select id, content_blocks, 'before content rewrite (c_nicet)' from lessons where id in ('c1acef29-f276-4afb-8bc1-6886b43e3aee', '4510af56-9417-41c1-8681-626e6593e1b0', '3ea1e879-8710-4c92-b6be-aa85f054ddf9', '23c7ce63-260e-478a-8b5c-653abcacb369', '22d51fc1-3903-4f2e-8c21-99c1b1174786', 'eec145a8-1257-4934-a22a-9a9154439d3d', '1b4a9d65-182d-4786-8427-2d2804c155f2', '447450fe-acab-481f-b749-e391985a1fca', 'a943b399-d65f-40bb-a68c-956a8f44ea67', '2343ac35-c506-4f81-a5c3-25492d96bc1e', 'e88c73e1-3fbf-47c1-a852-34753fdeadc0', '92be6a13-0f85-4e7c-8b17-5dfe046fb59c', '74e02135-a559-4e69-a56e-7b11bfec9b85', '4685892e-c937-4862-9947-3cd818c80b74', 'ef68518d-6134-4f02-b06d-9341a04c4b75', 'f6705826-e35d-4396-b410-a7db3a1c0494', '0a61f1c0-d51a-4532-95a7-dbc70cecd5ba', 'b64609bb-a3ec-4b78-9a6c-b9dd86ac16ab', 'fe55c901-6144-4e4c-9ee4-55c3ee078ba1', '7bc8e49c-933a-484f-b408-bd5ae4590056', '009204be-6dfa-4e14-9ed0-79cd8b04eb71', 'd67b7932-0c33-4238-9dc4-fa6101e51481', 'a6a69ab3-5938-46dc-980a-cd77ddf502ef', '201ddffe-ba0b-4fef-993c-975f62c8af4b', '07fbc29d-8572-4aa7-b2d9-279e9d49c88c', 'ac40f134-a140-4a56-9e0d-ae6ba0380156', '7e26f8c7-bbca-4957-a55c-156c0889ce9d', '3e40145f-b6fd-4fa7-9f00-8d8cc96333b1', '0de192e6-f106-43ee-b030-2f5e7a12ce64', '0692bb12-9a2c-4bd5-a98d-0faa8f0aeaaa')
  and not exists (select 1 from lesson_content_backup b where b.lesson_id = lessons.id and b.note = 'before content rewrite (c_nicet)');

-- How the NICET Path Works
update lessons set content_blocks = '[{"text": "How the NICET Path Works", "type": "title", "overview": "Understand the four NICET levels in Special Hazards Systems, what certification requires beyond passing an exam, and where Level I fits.", "examContext": "Passing the exam is only one requirement. Knowing the rest of the path early helps you plan your paperwork and your study time so nothing delays your certification."}, {"type": "paragraph", "text": "**NICET**, the National Institute for Certification in Engineering Technologies, certifies technicians in several fields. **Special Hazards Systems** has four levels, each building on the last."}, {"type": "diagram", "heading": "The four levels", "diagram": {"kind": "ladder", "rungs": [{"label": "Level IV", "note": "Senior technician: complex or specialized systems; supervises and trains others."}, {"label": "Level III", "note": "Works independently: inspect, maintain, repair, install and test."}, {"label": "Level II", "note": "Routine tasks under limited supervision. At least 2 years of experience."}, {"label": "Level I", "note": "Trainee under direct supervision: identifies wiring and devices, reads drawings, mounts devices and piping. At least 6 months of experience."}], "top": "most senior", "bottom": "entry"}}, {"type": "compare", "heading": "What certification takes beyond the exam", "columns": ["Applies at"], "rows": [{"label": "Pass the exam and meet lower-level requirements", "values": ["Every level"]}, {"label": "Documented work history", "values": ["Every level"]}, {"label": "Supervisor verification of key activities", "values": ["Every level"]}, {"label": "Personal recommendation", "values": ["Levels III and IV"]}, {"label": "Major project", "values": ["Level IV"]}, {"label": "Continuing development; recertify every three years", "values": ["Every level"]}]}, {"type": "callout", "variant": "info", "text": "You don''t have to hold a lower certification first, but you must meet its requirements. Exams are taken on computer at a Pearson VUE center, and applications go through the NICET portal. Check nicet.org for current fees and requirements."}, {"type": "callout", "variant": "info", "text": "This course is independent and is not affiliated with or endorsed by NICET or NFPA."}, {"type": "callout", "variant": "tip", "text": "Start your work history paperwork early. The exam is only one of the requirements."}]'::jsonb where id = 'c1acef29-f276-4afb-8bc1-6886b43e3aee';

-- What the Level I Exam Looks Like
update lessons set content_blocks = '[{"text": "What the Level I Exam Looks Like", "type": "title", "overview": "Learn the format of the Level I exam, how its five task areas are weighted, and the exam-day rules that affect how you should prepare.", "examContext": "Knowing the format ahead of time removes surprises. This course is built around the same five task areas and weights, so you always know how much of the exam each section represents."}, {"type": "term_set", "heading": "The exam at a glance", "terms": [{"term": "Updated exam", "short": "86 questions in 140 minutes, released November 2, 2026."}, {"term": "Earlier version", "short": "83 questions in the same 140 minutes."}, {"term": "Outline status", "short": "Still marked draft when this course was written; check NICET for changes."}]}, {"type": "compare", "heading": "The five task areas", "columns": ["Share of the exam"], "rows": [{"label": "1. Inspection, Testing, and Maintenance", "values": ["35 to 45%"]}, {"label": "2. Repair and Recharge", "values": ["7 to 17%"]}, {"label": "3. Installation", "values": ["15 to 25%"]}, {"label": "4. System Design and Configuration", "values": ["8 to 18%"]}, {"label": "5. Safety", "values": ["10 to 20%"]}]}, {"type": "term_set", "heading": "How it''s delivered", "terms": [{"term": "Format", "short": "Computer based at a proctored Pearson VUE center."}, {"term": "Navigation", "short": "One question at a time; you can go back to review."}, {"term": "Exhibits", "short": "Some questions open an exhibit; a few ask you to click part of a picture."}, {"term": "Multiple answers", "short": "Some questions have more than one correct answer, and tell you how many."}, {"term": "Calculator", "short": "On screen only; personal calculators aren''t allowed."}, {"term": "Score", "short": "An unofficial score report when you finish."}]}, {"type": "callout", "variant": "info", "text": "You sign a non-disclosure agreement before the exam. NICET owns its questions, so never share or post what you see."}, {"type": "callout", "variant": "tip", "text": "Inspection, Testing, and Maintenance is the biggest task area by far, so the course starts there."}]'::jsonb where id = '4510af56-9417-41c1-8681-626e6593e1b0';

-- How to Use Orivian
update lessons set content_blocks = '[{"text": "How to Use Orivian", "type": "title", "overview": "How a task area''s lessons, recap, and checkpoint fit together, what it takes to mark a lesson complete, and the tools that help you study.", "examContext": "Why this matters: understanding the platform''s rhythm up front means you spend your time studying, not figuring out the interface."}, {"type": "paragraph", "text": "Every task area in this course follows the same pattern. Learn it once and you know it everywhere."}, {"type": "diagram", "heading": "Inside a task area", "diagram": {"kind": "flow", "steps": [{"label": "Lessons", "note": "Each lesson ends in a 10-question mini-exam. 80% to pass; retake as often as you like."}, {"label": "Task area recap", "note": "The highest-yield facts from every lesson, plus rapid practice questions. No exam."}, {"label": "Task area checkpoint", "note": "A longer exam across the whole task area, with fresh scenarios. The real test of whether it stuck."}]}}, {"type": "term_set", "heading": "How a lesson is laid out", "terms": [{"term": "Key terms at a glance", "short": "Every term with a one-line definition, often next to a diagram."}, {"term": "Breakdown", "short": "Terms in depth, each with an \"In practice\" example."}, {"term": "Side by side", "short": "Comparison tables for the pairs the exam loves, with an exam cue row."}, {"term": "How this shows up on the exam", "short": "Practice questions: pick an answer, then see why it''s right and what the trap was. Not scored."}, {"term": "Mini-exam", "short": "The graded questions at the end. You can review every past attempt afterwards."}]}, {"type": "term_set", "heading": "Finding your way", "terms": [{"term": "The trail map", "short": "Each course page shows your path as a trail: covered ground in green, your next waypoint in gold."}, {"term": "Next waypoint", "short": "The card at the top of the course page always points to your next step."}, {"term": "Study timer", "short": "Counts only while a lesson or exam is visible in front of you. For your awareness; never graded."}, {"term": "Listen", "short": "Any slide can be read aloud. Turn on auto-play in Voice settings to hear each slide as you press Next."}, {"term": "Keyboard", "short": "Arrow keys move between slides, L listens, N opens notes."}]}, {"type": "term_set", "heading": "Your notes", "terms": [{"term": "Write a note", "short": "Open Notes in any lesson and type; it''s linked to that lesson automatically."}, {"term": "Save to notes", "short": "Select any sentence in a lesson and tap Save to notes to keep it as a quote."}, {"term": "My Notes", "short": "Everything you''ve saved, on the Notes page, grouped by course and lesson."}], "intro": "Notes are private to you and follow your account to any device."}, {"type": "callout", "variant": "tip", "text": "One or two lessons done attentively beat a skimmed marathon. Use the recap right before the checkpoint."}]'::jsonb where id = '3ea1e879-8710-4c92-b6be-aa85f054ddf9';

-- Using the Code Books Fast
update lessons set content_blocks = '[{"text": "Using the Code Books Fast", "type": "title", "overview": "Learn which four standards you may use during the exam, the rules for bringing printed copies, and how to find answers quickly without running out of time.", "examContext": "The exam rewards knowing where to look. With about 1.6 minutes per question, candidates who search efficiently finish with time to spare, and those who read whole chapters do not."}, {"type": "compare", "heading": "The four reference standards", "columns": ["Edition", "Covers"], "rows": [{"label": "NFPA 12", "values": ["2022", "Carbon dioxide extinguishing systems"]}, {"label": "NFPA 70", "values": ["2020", "National Electrical Code: wiring and raceways"]}, {"label": "NFPA 72", "values": ["2022", "Fire alarm and signaling: detection and control circuits"]}, {"label": "NFPA 2001", "values": ["2022", "Clean agent extinguishing systems"]}], "intro": "All four are on screen during the exam, searchable and view only."}, {"type": "compare", "heading": "Printed copies: allowed or not", "columns": ["Allowed", "Not allowed"], "rows": [{"label": "Binding", "values": ["Three-ring binder with a title page", "Loose papers"]}, {"label": "Marking", "values": ["Highlighting; permanently attached index tabs", "Handwritten notes; repositionable sticky tabs"]}, {"label": "Substitutes", "values": ["The standard itself", "An NFPA Handbook"]}]}, {"type": "diagram", "heading": "Finding answers fast", "diagram": {"kind": "flow", "steps": [{"label": "Pick the standard", "note": "CO2: NFPA 12. Clean agent: 2001. Detection: 72. Wiring: 70."}, {"label": "Search key nouns", "note": "Hold time, container, inspection."}, {"label": "Read the exact wording", "note": "Shall is required; should is a recommendation."}, {"label": "Watch the clock", "note": "About 1.6 minutes per question; flag and move on."}]}}, {"type": "scenario", "prompt": "A question asks about raceway fill for releasing circuit wiring. Which standard should you open first?", "choices": [{"id": "a", "text": "NFPA 12"}, {"id": "b", "text": "NFPA 70"}, {"id": "c", "text": "NFPA 2001"}, {"id": "d", "text": "NFPA 72"}], "answer": "b", "why": "Wiring and raceways are in the National Electrical Code."}, {"type": "scenario", "prompt": "A candidate wants to bring a printed NFPA 2001. Which is allowed?", "choices": [{"id": "a", "text": "Handwritten notes in the margins"}, {"id": "b", "text": "Permanently attached index tabs in a three-ring binder"}, {"id": "c", "text": "Sticky notes marking key pages"}, {"id": "d", "text": "An NFPA Handbook instead"}], "answer": "b", "why": "Tabs must be permanent; handwritten notes and repositionable tabs aren''t allowed."}, {"type": "callout", "variant": "tip", "text": "Practice as you study: whenever a lesson names a standard, open it and find the section yourself."}]'::jsonb where id = '23c7ce63-260e-478a-8b5c-653abcacb369';

-- Identifying System Types and Components
update lessons set content_blocks = '[{"text": "Identifying System Types and Components", "type": "title", "overview": "Learn to tell carbon dioxide and clean agent systems apart, recognize total flooding versus local application, and name the main component groups of a special hazards system: storage, distribution, detection, control, and notification.", "examContext": "Task 1.1.1 opens the largest area of the Level I exam. Expect short scenarios that describe a system or a part and ask what it is and what it does. NFPA 12 (carbon dioxide) and NFPA 2001 (clean agent) are both available on screen during the exam, so practice finding their definitions quickly."}, {"type": "paragraph", "text": "Special hazards systems protect places where water is a poor choice: **data centers**, **electrical rooms**, **flammable liquid areas** and **high-value assets** like archives. They discharge a gaseous agent instead. At Level I you focus on **NFPA 12** (carbon dioxide) and **NFPA 2001** (clean agents)."}, {"type": "compare", "heading": "Total flooding vs. local application", "columns": ["Total flooding", "Local application"], "rows": [{"label": "How", "values": ["Fills an enclosed space to a design concentration and holds it", "Discharges directly onto the burning surface or object"]}, {"label": "Agents", "values": ["CO2 and clean agents", "CO2"]}]}, {"type": "compare", "heading": "The agents", "columns": ["How it puts out fire", "Notes"], "rows": [{"label": "Halocarbon clean agent", "values": ["Mainly absorbs heat", "Liquid, pressurized with nitrogen; HFC-227ea, FK-5-1-12"]}, {"label": "Inert gas clean agent", "values": ["Lowers oxygen", "Nitrogen, argon or a blend, as high-pressure gas"]}, {"label": "Carbon dioxide", "values": ["Displaces oxygen", "Can kill in an occupied space; strict safety rules"]}]}, {"type": "compare", "heading": "How agents are stored", "columns": ["Storage"], "rows": [{"label": "High-pressure CO2", "values": ["Liquid in cylinders, about 850 psi at 70°F"]}, {"label": "Low-pressure CO2", "values": ["Refrigerated insulated tank near 0°F, about 300 psi"]}, {"label": "Halocarbon", "values": ["Liquid superpressurized with nitrogen, commonly 360 or 600 psi at 70°F"]}, {"label": "Inert gas", "values": ["Gas at very high pressure, often 2,000 psi or more"]}]}, {"type": "compare", "heading": "Component groups", "columns": ["Includes"], "rows": [{"label": "Storage", "values": ["Cylinders or tank, container valves, gauges"]}, {"label": "Distribution", "values": ["Piping, fittings, nozzles"]}, {"label": "Detection", "values": ["Smoke, heat, flame or air sampling detectors"]}, {"label": "Control", "values": ["Releasing panel, manual release, abort switch, lockout valve"]}, {"label": "Notification", "values": ["Horns, strobes, warning signs"]}, {"label": "Auxiliary", "values": ["Ventilation shutdown, dampers, door releases"]}]}, {"type": "scenario", "prompt": "A system discharges agent straight onto a dip tank''s surface rather than filling the room. What type is it?", "choices": [{"id": "a", "text": "Total flooding"}, {"id": "b", "text": "Local application"}, {"id": "c", "text": "Inert gas"}, {"id": "d", "text": "Air sampling"}], "answer": "b", "why": "Discharging onto the hazard itself is local application."}, {"type": "scenario", "prompt": "A clean agent extinguishes fire mainly by lowering the room''s oxygen. Which kind is it?", "choices": [{"id": "a", "text": "Halocarbon"}, {"id": "b", "text": "Inert gas"}, {"id": "c", "text": "Foam"}, {"id": "d", "text": "Dry chemical"}], "answer": "b", "why": "Inert gases lower oxygen; halocarbons mainly absorb heat."}, {"type": "callout", "variant": "tip", "text": "Identify a system from its nameplate and label, not a guess. Agent, quantity and manufacturer are printed there."}]'::jsonb where id = '22d51fc1-3903-4f2e-8c21-99c1b1174786';

-- Checking Detection, Control, and Mechanical Component Locations
update lessons set content_blocks = '[{"text": "Checking Detection, Control, and Mechanical Component Locations", "type": "title", "overview": "Learn how to compare the installed system against the approved drawings and documentation, spot devices that were moved, blocked, or removed, and report what you find.", "examContext": "Task 1.1.2 tests whether you can notice change. Questions often describe a site walk and ask which finding to report or which document to compare against. At Level I you observe and report. You do not approve or make design changes."}, {"type": "compare", "heading": "Shop drawings vs. as-built drawings", "columns": ["Shop drawings", "As-built drawings"], "rows": [{"label": "Show", "values": ["What is to be built: exact layout of piping, nozzles and devices", "What was actually installed, including field changes"]}, {"label": "When", "values": ["Before installation", "After installation"]}]}, {"type": "diagram", "heading": "A walk-through", "diagram": {"kind": "flow", "steps": [{"label": "Get the drawings", "note": "Approved drawings and documentation."}, {"label": "Check detectors", "note": "Where drawn and unobstructed."}, {"label": "Check stations", "note": "Manual release and abort accessible and labeled."}, {"label": "Find containers and panel"}, {"label": "Trace piping to nozzles", "note": "Present and unobstructed."}, {"label": "Note every change", "note": "Added, moved, removed, covered or damaged."}]}}, {"type": "term_set", "heading": "Changes that cause problems", "terms": [{"term": "New partitions, racks or ducts", "short": "Block detection or discharge."}, {"term": "Covers left on detectors", "short": "Dust covers, paint or bags after construction."}, {"term": "Stored items", "short": "Blocking a manual station or the panel."}, {"term": "Other trades", "short": "Moved or removed devices."}, {"term": "Nozzles", "short": "Moved, capped or painted."}]}, {"type": "scenario", "prompt": "During an inspection, a smoke detector still has its construction dust cover on. What should a Level I technician do?", "choices": [{"id": "a", "text": "Ignore it; it''s new"}, {"id": "b", "text": "Report it as a discrepancy"}, {"id": "c", "text": "Move the detector"}, {"id": "d", "text": "Change the design"}], "answer": "b", "why": "A covered detector can''t sense fire. Level I observes and reports."}, {"type": "scenario", "prompt": "A rack now blocks a nozzle that the drawings show in the open. What''s the right response?", "choices": [{"id": "a", "text": "Move the nozzle"}, {"id": "b", "text": "Report it to a supervisor"}, {"id": "c", "text": "Add another nozzle"}, {"id": "d", "text": "Cut the rack"}], "answer": "b", "why": "Even small moves change agent distribution; report it."}, {"type": "callout", "variant": "tip", "text": "Level I compares the site to the approved drawings and reports. It doesn''t redesign."}]'::jsonb where id = 'eec145a8-1257-4934-a22a-9a9154439d3d';

-- Inspecting Construction Features for Changes
update lessons set content_blocks = '[{"text": "Inspecting Construction Features for Changes", "type": "title", "overview": "Learn why a total flooding system depends on the room around it, and how to spot openings, propped doors, unsealed penetrations, and layout changes that can let agent escape or leave the design wrong.", "examContext": "Task 1.1.3 asks you to notice construction changes and understand why they matter. Expect scenarios where a wall, door, opening, or volume changes and you must pick the concern or the correct response."}, {"type": "paragraph", "text": "A total flooding system is designed for a specific **enclosure**. The agent must reach its **design concentration** and stay there for the **hold time**. Anything that lets agent escape or changes the room''s size can defeat the design."}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Enclosure integrity", "short": "The room''s ability to keep agent in at the required concentration."}, {"term": "Hold time", "short": "How long the design concentration must be maintained after discharge."}, {"term": "Penetration", "short": "An opening through a wall, floor or ceiling for pipes, cables or ducts."}]}, {"type": "term_set", "heading": "What to look for", "terms": [{"term": "Walls", "short": "No longer reaching the deck above or slab below."}, {"term": "Penetrations", "short": "New or unsealed openings for cable, conduit or pipe."}, {"term": "Doors", "short": "Propped open, damaged or not closing fully."}, {"term": "Ventilation", "short": "Ducts and dampers that wouldn''t close or shut down."}, {"term": "Room volume", "short": "Walls added or removed."}, {"term": "New hazards", "short": "Equipment or storage that changes what''s protected."}]}, {"type": "scenario", "prompt": "A contractor has run new cables through the wall of a clean agent room and left the hole unsealed. Why does it matter?", "choices": [{"id": "a", "text": "It looks untidy"}, {"id": "b", "text": "Agent may leak out and fail to hold its design concentration"}, {"id": "c", "text": "It blocks detectors"}, {"id": "d", "text": "It affects the panel''s battery"}], "answer": "b", "why": "Unsealed penetrations threaten enclosure integrity."}, {"type": "scenario", "prompt": "What should a Level I technician do about a damper that doesn''t close?", "choices": [{"id": "a", "text": "Adjust it"}, {"id": "b", "text": "Seal the duct"}, {"id": "c", "text": "Record it and report it"}, {"id": "d", "text": "Ignore it"}], "answer": "c", "why": "Never fix enclosure problems yourself; the design needs to be checked."}, {"type": "callout", "variant": "tip", "text": "Level II runs the room integrity test. Level I spots what would make it fail and reports it."}]'::jsonb where id = '1b4a9d65-182d-4786-8427-2d2804c155f2';

-- Activating Alarm Initiating Devices
update lessons set content_blocks = '[{"text": "Activating Alarm Initiating Devices", "type": "title", "overview": "Learn the types of initiating devices, how cross-zoned detection and pre-discharge alarms work, and the safe order of operations for functional testing: disable the release, test, restore, and verify.", "examContext": "Task 1.1.4 tests both device knowledge and safe procedure. Expect questions about what to do before, during, and after activating a device. NFPA 72 covers testing of the detection and signaling side, and it is available on screen during the exam."}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Initiating device", "short": "Starts an alarm or release: a detector or manual station."}, {"term": "Cross-zoned detection", "short": "Two or more detectors in separate zones must alarm before release."}, {"term": "Pre-discharge alarm", "short": "Audible and visual warning to leave before discharge."}, {"term": "Abort switch", "short": "Holds or stops the sequence during the pre-discharge delay, as programmed."}]}, {"type": "term_set", "heading": "Common initiating devices", "terms": [{"term": "Smoke detectors", "short": "Including air sampling."}, {"term": "Heat detectors", "short": "Respond to temperature."}, {"term": "Flame detectors", "short": "Respond to radiant energy from flame."}, {"term": "Manual stations", "short": "Pull or release stations."}]}, {"type": "diagram", "heading": "The safe test sequence", "diagram": {"kind": "flow", "steps": [{"label": "Notify", "note": "Monitoring station and occupants."}, {"label": "Disable the release", "note": "Disarm, lock out or disconnect per the manufacturer."}, {"label": "Activate each device", "note": "Manufacturer''s listed test method only."}, {"label": "Confirm indications", "note": "Panel and notification devices."}, {"label": "Restore and reset", "note": "Releasing circuits back, panel normal."}, {"label": "Notify completion"}]}}, {"type": "scenario", "prompt": "What must happen before a technician activates any detector on a clean agent system?", "choices": [{"id": "a", "text": "Open the room''s door"}, {"id": "b", "text": "Take the agent release out of service"}, {"id": "c", "text": "Disconnect the batteries"}, {"id": "d", "text": "Remove the cylinders"}], "answer": "b", "why": "An accidental discharge can injure people and is costly."}, {"type": "scenario", "prompt": "A technician wants to test a smoke detector with a lighter. What''s wrong?", "choices": [{"id": "a", "text": "Nothing"}, {"id": "b", "text": "Only the manufacturer''s listed test method should be used"}, {"id": "c", "text": "Lighters are too slow"}, {"id": "d", "text": "It must be tested with water"}], "answer": "b", "why": "Improvised methods can damage detectors and give false results."}, {"type": "callout", "variant": "tip", "text": "Always disable the release before activating anything, and restore it after."}]'::jsonb where id = '447450fe-acab-481f-b749-e391985a1fca';

-- Checking Agent Quantity and Pressure
update lessons set content_blocks = '[{"text": "Checking Agent Quantity and Pressure", "type": "title", "overview": "Learn how to verify that agent containers are within their documented range. CO2 is checked by weight, halocarbons by weight or level plus pressure, and inert gases by pressure, and each standard sets its own refill-or-replace limit.", "examContext": "Task 1.1.5 is one of the most testable in the outline because it mixes concepts with arithmetic. Expect questions that give a nameplate value and a measured value and ask whether the container is within range. NFPA 12 and NFPA 2001 are on screen during the exam, so know where their inspection and maintenance requirements are."}, {"type": "paragraph", "text": "A system only protects a space if its containers hold the right amount of agent. The **documented range** comes from the nameplate, the manufacturer''s data and the code. Both standards call for checks roughly every six months; confirm the interval in the edition on screen."}, {"type": "compare", "heading": "How each container is checked", "columns": ["Check by", "Refill or replace when"], "rows": [{"label": "High-pressure CO2", "values": ["Weighing; a gauge can''t show quantity", "More than 10% loss of net content (NFPA 12)"]}, {"label": "Low-pressure CO2", "values": ["Liquid level gauge and pressure; refrigeration holding", "Supervisory signals report problems"]}, {"label": "Halocarbon", "values": ["Weight or liquid level, plus pressure against the temperature chart", "More than 5% agent loss or more than 10% pressure loss, temperature adjusted (NFPA 2001)"]}, {"label": "Inert gas", "values": ["Pressure gauge, adjusted for temperature", "Pressure reflects quantity"]}]}, {"type": "key_term", "term": "The weight math", "definition": "Net = gross minus tare. Percent loss = (nameplate net minus measured net) divided by nameplate net.", "example": "Tare 68 lb, nameplate net 100 lb, scale reads 160 lb. Measured net is 92 lb, an 8% loss, within the 10% CO2 limit."}, {"type": "scenario", "prompt": "A high-pressure CO2 cylinder has tare 70 lb and nameplate net 50 lb. The scale reads 113 lb. What should happen?", "choices": [{"id": "a", "text": "Nothing; it''s within range"}, {"id": "b", "text": "Refill or replace it: the loss is 14%"}, {"id": "c", "text": "Check the gauge instead"}, {"id": "d", "text": "Vent it"}], "answer": "b", "why": "Measured net = 113 minus 70 = 43 lb. Loss = 7 divided by 50 = 14%, over NFPA 12''s 10% limit.", "trap": "Reading the gross weight against the net, or trusting a gauge, leads to the wrong call."}, {"type": "scenario", "prompt": "Why can''t a pressure gauge tell you how much agent is left in a high-pressure CO2 cylinder?", "choices": [{"id": "a", "text": "Gauges are inaccurate"}, {"id": "b", "text": "Pressure follows temperature, not the amount of liquid"}, {"id": "c", "text": "CO2 has no pressure"}, {"id": "d", "text": "The gauge reads weight"}], "answer": "b", "why": "A nearly empty cylinder can show normal pressure."}, {"type": "callout", "variant": "tip", "text": "CO2: weigh it, 10% limit. Halocarbon: 5% quantity or 10% pressure, temperature adjusted."}]'::jsonb where id = 'a943b399-d65f-40bb-a68c-956a8f44ea67';

-- Inspecting Clean Agent Cylinders and Discharge Hoses
update lessons set content_blocks = '[{"text": "Inspecting Clean Agent Cylinders and Discharge Hoses", "type": "title", "overview": "Learn what to look for on agent cylinders and flexible discharge hoses: corrosion, dents, bulges, fire damage, loose brackets, cracked hoses, and overdue hydrostatic tests, plus how to handle a charged cylinder safely.", "examContext": "Task 1.1.6 is a visual inspection task. Expect scenarios describing a cylinder or hose condition and asking whether to report it or remove it from service. The compressed gas cylinder inspection standard CGA C-6 is on your study list, but it is not allowed in the test center."}, {"type": "compare", "heading": "Cylinder and hose checks", "columns": ["Cylinders", "Discharge hoses"], "rows": [{"label": "Damage", "values": ["Corrosion, pitting, dents, gouges, bulges", "Cracks, cuts, abrasion, kinks, crushing, bulges"]}, {"label": "Other", "values": ["Fire or heat damage; leaks at valve or fittings", "Loose, corroded or damaged fittings"]}, {"label": "Mounting and labels", "values": ["Brackets secure; label and nameplate readable", "Test or replacement date if marked"]}, {"label": "Dates", "values": ["Hydrostatic test date current", "As marked"]}]}, {"type": "key_term", "term": "Hydrostatic test", "definition": "A periodic pressure test proving a cylinder can hold its rated pressure, commonly every 5 or 10 years depending on the cylinder specification.", "example": "A cylinder stamped with a test date 12 years ago, on a 10-year specification, is overdue and gets reported."}, {"type": "key_term", "term": "CGA C-6", "definition": "The compressed gas industry standard for visually inspecting steel cylinders. On the NICET study list, but not allowed in the test center.", "example": "It''s the reference for what counts as a rejectable dent or pit."}, {"type": "scenario", "prompt": "A cylinder has a bulge near its base. What should happen?", "choices": [{"id": "a", "text": "Note it for next year"}, {"id": "b", "text": "Remove it from service and report it"}, {"id": "c", "text": "Repaint it"}, {"id": "d", "text": "Tighten the bracket"}], "answer": "b", "why": "Bulges are a serious defect."}, {"type": "scenario", "prompt": "A charged cylinder must be moved. What comes first?", "choices": [{"id": "a", "text": "Carry it by the valve"}, {"id": "b", "text": "Disconnect the actuator and fit the protective cap over the valve outlet"}, {"id": "c", "text": "Roll it on its side"}, {"id": "d", "text": "Open the valve slightly"}], "answer": "b", "why": "A knocked-off valve can launch a cylinder like a rocket."}, {"type": "callout", "variant": "tip", "text": "Never move a charged cylinder by its valve. Actuator off, cap on, first."}]'::jsonb where id = '2343ac35-c506-4f81-a5c3-25492d96bc1e';

-- Inspecting Piping and Hangers
update lessons set content_blocks = '[{"text": "Inspecting Piping and Hangers", "type": "title", "overview": "Learn what a visual piping inspection covers: supports and hangers, corrosion, unauthorized changes, and nozzle position, orientation, and condition.", "examContext": "Task 1.1.7 rounds out Task Area 1. Expect scenarios describing a hanger, nozzle, or piece of pipe and asking what the concern is and what to do."}, {"type": "paragraph", "text": "Agent piping carries agent at high speed and pressure during discharge. It must be **supported**, **intact** and exactly as designed."}, {"type": "compare", "heading": "Piping vs. nozzle checks", "columns": ["Piping and hangers", "Nozzles"], "rows": [{"label": "Position", "values": ["Hangers present, tight, not sagging", "Where the drawings show, pointing as designed"]}, {"label": "Condition", "values": ["No corrosion, dents or damage", "Clean, unpainted, undamaged"]}, {"label": "Changes", "values": ["No added branches or capped stubs; nothing hung from it", "Area around each nozzle clear"]}, {"label": "Labels and caps", "values": ["Identification in place", "Blow-off caps in place where used"]}]}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Hanger", "short": "Holds piping in place and resists discharge reaction forces."}, {"term": "Blow-off cap", "short": "Keeps debris out of a nozzle; releases on discharge."}]}, {"type": "scenario", "prompt": "A painter has coated a discharge nozzle. What should a Level I technician do?", "choices": [{"id": "a", "text": "Scrape the paint off"}, {"id": "b", "text": "Report it"}, {"id": "c", "text": "Replace the nozzle"}, {"id": "d", "text": "Ignore it"}], "answer": "b", "why": "Paint can block or change the orifice; report rather than clean it yourself."}, {"type": "scenario", "prompt": "An electrician has hung a cable tray from the agent piping. What''s the concern?", "choices": [{"id": "a", "text": "None"}, {"id": "b", "text": "Nothing may be hung from agent piping"}, {"id": "c", "text": "Cable trays block detectors"}, {"id": "d", "text": "It voids the panel warranty"}], "answer": "b", "why": "It adds load and can shift piping during discharge."}, {"type": "callout", "variant": "tip", "text": "Visual inspection and report. Puff and pressure tests are done at higher levels."}]'::jsonb where id = 'e88c73e1-3fbf-47c1-a852-34753fdeadc0';

-- Task Area 1 Recap: Inspection, Testing, and Maintenance
update lessons set content_blocks = '[{"text": "Task Area 1 Recap: Inspection, Testing, and Maintenance", "type": "title", "overview": "A one-page review of the highest-yield facts from the seven lessons in this task area.", "examContext": "This recap has no questions of its own. The Task Area 1 checkpoint draws from all seven lessons, and this task area makes up roughly 35 to 45 percent of the Level I exam."}, {"type": "term_set", "heading": "Systems and components", "terms": [{"term": "NFPA 12 / 2001 / 72 / 70", "short": "CO2 / clean agent / detection and signaling / electrical code."}, {"term": "Halocarbon / inert / CO2", "short": "Absorbs heat / lowers oxygen / displaces oxygen, can kill."}, {"term": "Storage", "short": "High-pressure CO2 about 850 psi; low-pressure CO2 near 0°F and 300 psi."}]}, {"type": "term_set", "heading": "Inspection habits", "terms": [{"term": "Drawings", "short": "Compare the site to the approved drawings."}, {"term": "Report", "short": "Level I doesn''t redesign."}, {"term": "Enclosure", "short": "Doors, openings, penetrations, dampers, volume."}, {"term": "Testing", "short": "Disable release, listed test method, restore."}]}, {"type": "term_set", "heading": "Numbers and hardware", "terms": [{"term": "CO2", "short": "Weigh it; over 10% net loss means refill or replace."}, {"term": "Halocarbon", "short": "Over 5% quantity or 10% pressure loss, temperature adjusted."}, {"term": "Weight math", "short": "Net = gross minus tare."}, {"term": "Moving cylinders", "short": "Actuator off, cap on."}, {"term": "Nozzles", "short": "Never paint; report."}]}, {"type": "scenario", "prompt": "Which standard covers clean agent systems?", "choices": [{"id": "a", "text": "NFPA 12"}, {"id": "b", "text": "NFPA 2001"}, {"id": "c", "text": "NFPA 70"}, {"id": "d", "text": "NFPA 72"}], "answer": "b", "why": "NFPA 2001."}, {"type": "scenario", "prompt": "Tare 60 lb, nameplate net 100 lb, scale reads 155 lb. CO2 loss?", "choices": [{"id": "a", "text": "5%"}, {"id": "b", "text": "15%"}, {"id": "c", "text": "10%"}, {"id": "d", "text": "45%"}], "answer": "a", "why": "Net 95 lb, a 5% loss."}, {"type": "scenario", "prompt": "What comes before activating a detector during testing?", "choices": [{"id": "a", "text": "Reset the panel"}, {"id": "b", "text": "Disable the agent release"}, {"id": "c", "text": "Open the doors"}, {"id": "d", "text": "Call the AHJ"}], "answer": "b", "why": "Take the release out of service."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Task Area 1 Checkpoint: fresh questions from all seven lessons."}]'::jsonb where id = '92be6a13-0f85-4e7c-8b17-5dfe046fb59c';

-- Replacing Damaged Wires
update lessons set content_blocks = '[{"text": "Replacing Damaged Wires", "type": "title", "overview": "Learn the safe order of operations for replacing damaged wiring on a detection, control, or notification circuit, and how to confirm the circuit is supervised and normal afterward.", "examContext": "Task 1.2.1 combines electrical basics with system safety. Expect scenarios about what to do before working on a circuit, what wire is acceptable, and what the panel should show when the job is done. NFPA 70 and NFPA 72 are both available on screen."}, {"type": "paragraph", "text": "Fire alarm and releasing circuits fall under **NFPA 70** and **NFPA 72**. The panel **supervises** them, so a repair must leave the circuit intact and supervised."}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Supervised circuit", "short": "Monitored so a break or ground shows as trouble."}, {"term": "Open circuit", "short": "A break or loose connection that stops current."}, {"term": "Ground fault", "short": "An unintended connection to ground."}, {"term": "Polarity", "short": "Positive and negative orientation; many devices need it right."}]}, {"type": "diagram", "heading": "A wiring repair, in order", "diagram": {"kind": "flow", "steps": [{"label": "Identify the circuit", "note": "From drawings and labels."}, {"label": "Notify and disable release"}, {"label": "De-energize and verify", "note": "Lockout and tagout; meter check."}, {"label": "Note colors and terminals"}, {"label": "Repair", "note": "Same type, gauge and listing; listed accessible enclosures; correct polarity."}, {"label": "Confirm normal", "note": "No open or ground trouble; devices work."}, {"label": "Restore, notify, document"}]}}, {"type": "scenario", "prompt": "After replacing a damaged section of wire, the panel shows a ground fault trouble. Is the job done?", "choices": [{"id": "a", "text": "Yes"}, {"id": "b", "text": "No; the circuit must show normal before restoring"}, {"id": "c", "text": "Yes, if the devices work"}, {"id": "d", "text": "Only if the AHJ approves"}], "answer": "b", "why": "The panel must show normal with no open or ground trouble."}, {"type": "scenario", "prompt": "Where may splices be made?", "choices": [{"id": "a", "text": "Taped and hidden above the ceiling"}, {"id": "b", "text": "At terminals or in accessible, listed enclosures"}, {"id": "c", "text": "Anywhere convenient"}, {"id": "d", "text": "Inside the conduit"}], "answer": "b", "why": "Hidden taped splices aren''t acceptable."}, {"type": "callout", "variant": "tip", "text": "Never work on an energized circuit, or on a releasing circuit with the release armed."}]'::jsonb where id = '74e02135-a559-4e69-a56e-7b11bfec9b85';

-- Replacing Damaged Mechanical System Components
update lessons set content_blocks = '[{"text": "Replacing Damaged Mechanical System Components", "type": "title", "overview": "Learn which mechanical parts commonly need replacing, why replacements must be manufacturer-listed, and the safe order of work on a system with pressurized agent.", "examContext": "Task 1.2.2 tests safe procedure and part selection. Expect scenarios about what must be done before opening the discharge path, which replacement is acceptable, and what to do after the work."}, {"type": "term_set", "heading": "Parts you may replace", "terms": [{"term": "Actuator", "short": "Opens the container valve when signaled."}, {"term": "Pressure switch", "short": "Reports low or high container pressure as supervisory or trouble."}, {"term": "Check valve", "short": "One-way flow; prevents backflow into an empty or removed container."}, {"term": "Also", "short": "Nozzles, discharge hoses, container valves and fittings, gauges, manifold fittings."}]}, {"type": "diagram", "heading": "A safe sequence", "diagram": {"kind": "flow", "steps": [{"label": "Identify the part", "note": "Part number and listing from the manual."}, {"label": "Notify and disable release"}, {"label": "Disconnect actuators", "note": "Fit protective caps."}, {"label": "Isolate per the manufacturer", "note": "Never loosen a charged path."}, {"label": "Install the listed replacement", "note": "Tightened to specification."}, {"label": "Leak check and confirm pressure"}, {"label": "Reconnect actuators last", "note": "Once the panel shows normal."}, {"label": "Restore, notify, document"}]}}, {"type": "key_term", "term": "Recharge", "definition": "Discharged or low containers are refilled by qualified service personnel with proper equipment, and must be within their hydrostatic test date before returning to service.", "example": "After a discharge, cylinders go to an authorized fill facility rather than being topped up on site."}, {"type": "scenario", "prompt": "A technician finds a nozzle from another manufacturer that threads onto the pipe. Can it be used?", "choices": [{"id": "a", "text": "Yes, if it fits"}, {"id": "b", "text": "No; only manufacturer-listed parts"}, {"id": "c", "text": "Yes, with sealant"}, {"id": "d", "text": "Only temporarily"}], "answer": "b", "why": "The wrong nozzle changes flow and can defeat the design."}, {"type": "scenario", "prompt": "When are actuators reconnected?", "choices": [{"id": "a", "text": "First"}, {"id": "b", "text": "Before the leak check"}, {"id": "c", "text": "Last, once the panel shows normal"}, {"id": "d", "text": "Never"}], "answer": "c", "why": "Reconnecting last avoids accidental discharge."}, {"type": "callout", "variant": "tip", "text": "Actuators off and caps on first; actuators back on last. Listed parts only."}]'::jsonb where id = '4685892e-c937-4862-9947-3cd818c80b74';

-- Task Area 2 Recap: Repair and Recharge
update lessons set content_blocks = '[{"text": "Task Area 2 Recap: Repair and Recharge", "type": "title", "overview": "A short review of the highest-yield facts from the two lessons in this task area.", "examContext": "This recap has no questions of its own. The Task Area 2 checkpoint draws from both lessons, and this task area makes up roughly 7 to 17 percent of the Level I exam."}, {"type": "term_set", "heading": "Wiring repairs", "terms": [{"term": "Before", "short": "Notify, disable release, de-energize and verify."}, {"term": "Wire", "short": "Same type, gauge and listing."}, {"term": "Connections", "short": "Terminals or accessible listed enclosures; correct polarity."}, {"term": "After", "short": "Panel normal, devices work, restore and document."}]}, {"type": "term_set", "heading": "Mechanical repairs", "terms": [{"term": "Before", "short": "Actuators off, caps on."}, {"term": "Parts", "short": "Manufacturer listed only."}, {"term": "Never", "short": "Loosen fittings on a charged path."}, {"term": "After", "short": "Reconnect actuators last."}, {"term": "Recharge", "short": "Qualified service personnel only."}]}, {"type": "scenario", "prompt": "What does a supervised circuit do when it opens?", "choices": [{"id": "a", "text": "Discharges agent"}, {"id": "b", "text": "Reports a trouble signal"}, {"id": "c", "text": "Nothing"}, {"id": "d", "text": "Resets itself"}], "answer": "b", "why": "The panel reports it."}, {"type": "scenario", "prompt": "What prevents agent flowing back into a removed container?", "choices": [{"id": "a", "text": "Actuator"}, {"id": "b", "text": "Check valve"}, {"id": "c", "text": "Pressure switch"}, {"id": "d", "text": "Nozzle"}], "answer": "b", "why": "A check valve."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Task Area 2 Checkpoint."}]'::jsonb where id = 'ef68518d-6134-4f02-b06d-9341a04c4b75';

-- Getting Installation Information from Shop Drawings
update lessons set content_blocks = '[{"text": "Getting Installation Information from Shop Drawings", "type": "title", "overview": "Learn what is on a shop drawing, how to read its symbols and revision information, and how to use an architect''s or engineer''s scale to find real lengths.", "examContext": "Task 1.3.1 tests whether you can pull the right information from drawings. Expect questions that ask where information is found, which revision to use, or that give a scale and a measured length and ask for the real distance."}, {"type": "compare", "heading": "What''s on a shop drawing", "columns": ["Shows"], "rows": [{"label": "Title block", "values": ["Project, drawing number, date and revision"]}, {"label": "Legend", "values": ["What every symbol means; NFPA 170 gives standard symbols"]}, {"label": "Plan views", "values": ["Locations of devices, nozzles, containers and piping"]}, {"label": "Isometric", "values": ["3D piping view with lengths and elevation changes"]}, {"label": "Schedules and parts lists", "values": ["Sizes, quantities, part numbers"]}, {"label": "Notes", "values": ["Requirements for the whole installation"]}]}, {"type": "key_term", "term": "Scale", "definition": "Real length equals the measured length divided by the scale ratio. Check the scale on each view; one sheet can have several.", "example": "At 1/4 inch = 1 foot, a 3-inch line is 3 ÷ 0.25 = 12 feet. At 1 inch = 20 feet, a 2.5-inch line is 2.5 × 20 = 50 feet."}, {"type": "key_term", "term": "Revision", "definition": "A dated update to a drawing. Always install from the latest approved revision.", "example": "Revision C moved two nozzles; installing from revision B would put them in the wrong place."}, {"type": "scenario", "prompt": "On a drawing scaled 1/8 inch = 1 foot, a pipe run measures 4 inches. How long is it?", "choices": [{"id": "a", "text": "4 feet"}, {"id": "b", "text": "16 feet"}, {"id": "c", "text": "32 feet"}, {"id": "d", "text": "48 feet"}], "answer": "c", "why": "4 ÷ 0.125 = 32 feet."}, {"type": "scenario", "prompt": "The drawing shows a nozzle where there''s now a beam in the field. What should the installer do?", "choices": [{"id": "a", "text": "Move it a few feet"}, {"id": "b", "text": "Stop and ask before installing"}, {"id": "c", "text": "Skip that nozzle"}, {"id": "d", "text": "Install it under the beam"}], "answer": "b", "why": "Don''t guess or change the design."}, {"type": "callout", "variant": "tip", "text": "Latest approved revision, check the scale on each view, and ask when the field disagrees."}]'::jsonb where id = 'f6705826-e35d-4396-b410-a7db3a1c0494';

-- Installing Raceways and Conduit
update lessons set content_blocks = '[{"text": "Installing Raceways and Conduit", "type": "title", "overview": "Learn the basic rules for installing conduit and other raceways that carry special hazards system wiring: support, reaming, bend limits, fill limits, separation, and sealing openings into protected enclosures.", "examContext": "Task 1.3.2 draws on NFPA 70, which is available on screen during the exam. Expect questions on bend limits, fill percentages, support, and good installation practice."}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Raceway", "short": "An enclosed channel that holds and protects wiring; conduit is the most common."}, {"term": "Pull point", "short": "A box or conduit body for pulling or splicing conductors."}, {"term": "Conduit fill", "short": "The share of the raceway taken by conductors, limited for pulling and heat."}]}, {"type": "compare", "heading": "Fill limits (NFPA 70 Chapter 9, Table 1)", "columns": ["Maximum fill"], "rows": [{"label": "One conductor", "values": ["53%"]}, {"label": "Two conductors", "values": ["31%"]}, {"label": "More than two", "values": ["40%"]}]}, {"type": "term_set", "heading": "Good practice", "terms": [{"term": "Bends", "short": "No more than four quarter bends, 360 degrees, between pull points. A 45 counts as half."}, {"term": "Ream", "short": "Remove burrs from cut ends."}, {"term": "Support EMT", "short": "Generally within 3 feet of each box and every 10 feet or less; confirm in NFPA 70."}, {"term": "Separation and bonding", "short": "Keep circuits separated; ground and bond as required."}, {"term": "Seal", "short": "Where a raceway enters a protected room."}]}, {"type": "scenario", "prompt": "Between two pull points, a run has three 90-degree bends and two 45-degree bends. Is it within the limit?", "choices": [{"id": "a", "text": "Yes, 360 degrees exactly"}, {"id": "b", "text": "No, it''s 450 degrees"}, {"id": "c", "text": "Yes, 270 degrees"}, {"id": "d", "text": "No, 45s count double"}], "answer": "a", "why": "Three 90s are 270 degrees plus two 45s at 90 degrees: 360 total."}, {"type": "scenario", "prompt": "What''s the maximum fill for a conduit with three conductors?", "choices": [{"id": "a", "text": "53%"}, {"id": "b", "text": "31%"}, {"id": "c", "text": "40%"}, {"id": "d", "text": "60%"}], "answer": "c", "why": "More than two conductors: 40%."}, {"type": "callout", "variant": "tip", "text": "Four quarter bends, 360 degrees, between pull points. Fill: 53, 31, 40."}]'::jsonb where id = '0a61f1c0-d51a-4532-95a7-dbc70cecd5ba';

-- Installing Piping for a Special Hazards System
update lessons set content_blocks = '[{"text": "Installing Piping for a Special Hazards System", "type": "title", "overview": "Learn why agent piping must match the design, how to prepare and clean pipe, how to support it, and why nozzles go in last.", "examContext": "Task 1.3.3 rewards understanding of why the design cannot be changed in the field. NFPA 12 and NFPA 2001 are on screen during the exam, and both call for piping installed as designed."}, {"type": "paragraph", "text": "Agent piping is designed with **hydraulic calculations** that fix pipe sizes, lengths, fittings and nozzle orifices so the right amount of agent reaches each nozzle in time. Change any of these and the flow changes."}, {"type": "key_term", "term": "Orifice", "definition": "The nozzle opening that meters agent flow. Its size is part of the design.", "example": "Swapping in a nozzle with a larger orifice starves the nozzles further down the line."}, {"type": "diagram", "heading": "Installing it correctly", "diagram": {"kind": "flow", "steps": [{"label": "Specified pipe and fittings only"}, {"label": "Cut, ream, clean", "note": "Remove oil, scale and debris inside."}, {"label": "Cap open ends"}, {"label": "Fittings as drawn", "note": "Tees in the drawn orientation."}, {"label": "Sealant on male threads only"}, {"label": "Support", "note": "At spacing and near turns and nozzles."}, {"label": "Nozzles last"}]}}, {"type": "scenario", "prompt": "To avoid a duct, an installer wants to add one extra elbow to an agent pipe run. What''s the issue?", "choices": [{"id": "a", "text": "None"}, {"id": "b", "text": "Extra fittings change friction loss and can throw off the calculated flow"}, {"id": "c", "text": "Elbows aren''t allowed at all"}, {"id": "d", "text": "It needs a larger nozzle"}], "answer": "b", "why": "Don''t change the design in the field; ask."}, {"type": "scenario", "prompt": "Why are nozzles installed last?", "choices": [{"id": "a", "text": "They''re expensive"}, {"id": "b", "text": "So debris from installation doesn''t clog them"}, {"id": "c", "text": "They''re installed by the AHJ"}, {"id": "d", "text": "To save time"}], "answer": "b", "why": "The piping must be clean first."}, {"type": "callout", "variant": "tip", "text": "Hydraulic calculations fix the design. No added fittings, branches or size changes."}]'::jsonb where id = 'b64609bb-a3ec-4b78-9a6c-b9dd86ac16ab';

-- Installing Air Sampling Piping
update lessons set content_blocks = '[{"text": "Installing Air Sampling Piping", "type": "title", "overview": "Learn how air sampling smoke detection works and why its pipe network must be installed exactly as designed, with airtight joints and correct hole positions and end caps.", "examContext": "Task 1.3.4 is a short, focused topic drawn from NFPA 72, which is on screen during the exam. Expect questions on what the system is and why the design cannot be changed."}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Air sampling detector", "short": "Draws air through a pipe network to a sensing unit; very early detection."}, {"term": "Sampling hole", "short": "A precisely sized hole that pulls air from the space."}, {"term": "Transport time", "short": "How long smoke takes to travel from a hole to the detector; part of the design."}]}, {"type": "paragraph", "text": "Air sampling is used where very early warning matters, like data centers and clean rooms. The pipe network is designed with software that balances airflow and transport time. **NFPA 72** covers it."}, {"type": "term_set", "heading": "Installing it correctly", "terms": [{"term": "Pipe", "short": "Manufacturer-approved sampling pipe and fittings."}, {"term": "As designed", "short": "Lengths, fittings, hole sizes and positions, end caps."}, {"term": "Airtight", "short": "Every joint, except the sampling holes."}, {"term": "Clear holes", "short": "Away from tiles, insulation and obstructions."}, {"term": "Support and label", "short": "Accessible for maintenance."}]}, {"type": "scenario", "prompt": "An installer drills one extra hole to cover a new corner of the room. What''s wrong?", "choices": [{"id": "a", "text": "Nothing"}, {"id": "b", "text": "Any change alters airflow and can delay detection"}, {"id": "c", "text": "Holes should be taped"}, {"id": "d", "text": "The detector needs a reset only"}], "answer": "b", "why": "The network is balanced by design software."}, {"type": "scenario", "prompt": "Why must joints be airtight?", "choices": [{"id": "a", "text": "To hold agent"}, {"id": "b", "text": "So air is only drawn through the designed sampling holes"}, {"id": "c", "text": "To meet NFPA 70"}, {"id": "d", "text": "To reduce weight"}], "answer": "b", "why": "Leaks change where samples come from."}, {"type": "callout", "variant": "tip", "text": "Air sampling pipe follows its design exactly: holes, joints, end caps."}]'::jsonb where id = 'fe55c901-6144-4e4c-9ee4-55c3ee078ba1';

-- Mounting Special Hazards System Components
update lessons set content_blocks = '[{"text": "Mounting Special Hazards System Components", "type": "title", "overview": "Learn the rules for mounting agent containers, nozzles, detectors, manual stations, and signs so they are secure, accessible, and match the design.", "examContext": "Task 1.3.5 covers physical installation of the system''s parts. NFPA 12 and NFPA 2001 are on screen during the exam and describe container and nozzle requirements."}, {"type": "term_set", "heading": "Agent containers", "terms": [{"term": "Secure", "short": "Brackets and straps rated for the weight."}, {"term": "Temperature", "short": "Within the manufacturer''s range; away from sun and heat."}, {"term": "Protect", "short": "From physical damage."}, {"term": "Readable", "short": "Nameplate and gauge visible."}, {"term": "Service clearance", "short": "Room to weigh, service and replace."}, {"term": "Structure", "short": "Floor can carry the load."}]}, {"type": "compare", "heading": "Other components", "columns": ["Mount"], "rows": [{"label": "Nozzles", "values": ["At the drawn location, height, orientation and orifice; clear"]}, {"label": "Detectors", "values": ["Drawn locations; manufacturer spacing and ceiling rules"]}, {"label": "Manual release and abort stations", "values": ["Accessible; operable part typically 42 to 48 inches above the floor"]}, {"label": "Panels, horns, strobes", "values": ["Accessible, as drawn"]}, {"label": "Warning signs", "values": ["At entrances to the protected space"]}]}, {"type": "key_term", "term": "Service clearance", "definition": "Space kept clear so equipment can be inspected, serviced and replaced.", "example": "Cylinders jammed against a wall can''t be lifted onto a scale, so semiannual weighing becomes impossible."}, {"type": "scenario", "prompt": "Containers are being mounted in a sunny mechanical yard. What''s the concern?", "choices": [{"id": "a", "text": "None"}, {"id": "b", "text": "Temperature outside the manufacturer''s range affects pressure and performance"}, {"id": "c", "text": "Labels fade"}, {"id": "d", "text": "Gauges stop working"}], "answer": "b", "why": "Keep containers within their rated temperature range."}, {"type": "scenario", "prompt": "When is the actuator connected to a newly mounted container?", "choices": [{"id": "a", "text": "Before securing it"}, {"id": "b", "text": "Last, after it''s secured"}, {"id": "c", "text": "Before the cap is removed"}, {"id": "d", "text": "Never"}], "answer": "b", "why": "Keep the cap on until secured; actuator last."}, {"type": "callout", "variant": "tip", "text": "Containers secured, readable and serviceable. Manual stations around 42 to 48 inches; confirm in NFPA 72."}]'::jsonb where id = '7bc8e49c-933a-484f-b408-bd5ae4590056';

-- Task Area 3 Recap: Installation
update lessons set content_blocks = '[{"text": "Task Area 3 Recap: Installation", "type": "title", "overview": "A short review of the highest-yield facts from the five lessons in this task area.", "examContext": "This recap has no questions of its own. The Task Area 3 checkpoint draws from all five lessons, and this task area makes up roughly 15 to 25 percent of the Level I exam."}, {"type": "term_set", "heading": "Drawings and raceways", "terms": [{"term": "Revision", "short": "Latest approved."}, {"term": "Scale", "short": "Real length = measured ÷ scale ratio."}, {"term": "Bends", "short": "Four quarter bends, 360 degrees, between pull points."}, {"term": "Fill", "short": "53% one, 31% two, 40% more than two."}, {"term": "Seal", "short": "Raceway openings into protected rooms."}]}, {"type": "term_set", "heading": "Piping and mounting", "terms": [{"term": "Agent piping", "short": "Hydraulic design; no field changes; clean; nozzles last."}, {"term": "Air sampling", "short": "Holes, joints and end caps as designed; airtight."}, {"term": "Containers", "short": "Secured, readable, serviceable, out of heat."}, {"term": "Manual stations", "short": "Typically 42 to 48 inches."}, {"term": "Order", "short": "Cap on until secured; actuator last."}]}, {"type": "scenario", "prompt": "At 1/4 inch = 1 foot, a 5-inch line is how long?", "choices": [{"id": "a", "text": "5 feet"}, {"id": "b", "text": "20 feet"}, {"id": "c", "text": "1.25 feet"}, {"id": "d", "text": "50 feet"}], "answer": "b", "why": "5 ÷ 0.25 = 20."}, {"type": "scenario", "prompt": "Maximum fill for one conductor?", "choices": [{"id": "a", "text": "31%"}, {"id": "b", "text": "40%"}, {"id": "c", "text": "53%"}, {"id": "d", "text": "60%"}], "answer": "c", "why": "53%."}, {"type": "scenario", "prompt": "Which component goes in last on agent piping?", "choices": [{"id": "a", "text": "Hangers"}, {"id": "b", "text": "Nozzles"}, {"id": "c", "text": "Tees"}, {"id": "d", "text": "Pipe caps"}], "answer": "b", "why": "Nozzles last."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Task Area 3 Checkpoint."}]'::jsonb where id = '009204be-6dfa-4e14-9ed0-79cd8b04eb71';

-- Deriving Installation Information from Plans and Specifications
update lessons set content_blocks = '[{"text": "Deriving Installation Information from Plans and Specifications", "type": "title", "overview": "Learn which plans show which information, how to work out room volume, what specifications add, and what to do when plans and specifications disagree.", "examContext": "Task 1.4.1 tests whether you can find and use project information. Expect questions about which drawing shows what, simple volume math, and the correct response to a conflict."}, {"type": "compare", "heading": "Which drawing shows what", "columns": ["Shows"], "rows": [{"label": "Architectural floor plan", "values": ["Walls, doors, room sizes, layout"]}, {"label": "Reflected ceiling plan", "values": ["Ceiling items: lights, diffusers, detectors"]}, {"label": "Sections and elevations", "values": ["Heights, ceiling types, raised floors"]}, {"label": "Mechanical plan", "values": ["Ducts, dampers, equipment through the enclosure"]}, {"label": "Electrical plan", "values": ["Power, panels, conduit routes"]}]}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Reflected ceiling plan", "short": "The ceiling as if reflected in a mirror on the floor."}, {"term": "Specifications", "short": "Written requirements for products, materials and workmanship."}, {"term": "RFI", "short": "A formal written question asking the designer to clarify."}]}, {"type": "key_term", "term": "Room volume", "definition": "Length × width × height. Agent quantity is calculated from it, so mistakes matter.", "example": "A room 20 ft × 15 ft with a 10 ft ceiling is 3,000 cubic feet."}, {"type": "scenario", "prompt": "Where would you find where smoke detectors are mounted in a ceiling?", "choices": [{"id": "a", "text": "Electrical plan"}, {"id": "b", "text": "Reflected ceiling plan"}, {"id": "c", "text": "Mechanical plan"}, {"id": "d", "text": "Specifications"}], "answer": "b", "why": "Ceiling-mounted items."}, {"type": "scenario", "prompt": "The specifications call for one detector model and the plans show another. What should a Level I technician do?", "choices": [{"id": "a", "text": "Pick the cheaper one"}, {"id": "b", "text": "Submit an RFI or report it and wait"}, {"id": "c", "text": "Use whichever is in stock"}, {"id": "d", "text": "Install both"}], "answer": "b", "why": "Don''t choose for yourself."}, {"type": "callout", "variant": "tip", "text": "Volume = L × W × H. Conflicts go to an RFI, never your own judgment call."}]'::jsonb where id = 'd67b7932-0c33-4238-9dc4-fa6101e51481';

-- Basic Electrical Units and Components
update lessons set content_blocks = '[{"text": "Basic Electrical Units and Components", "type": "title", "overview": "Learn the four basic electrical units, how to use Ohm''s law and the power formula, and what common components such as end-of-line resistors, diodes, relays, and batteries do in a system.", "examContext": "Task 1.4.2 is where the exam''s math and component questions live. NFPA 72 is on screen, and Ugly''s Electrical References is a useful field guide though not allowed in the test center."}, {"type": "compare", "heading": "The four units", "columns": ["Unit", "Means"], "rows": [{"label": "Voltage", "values": ["Volts (V)", "Electrical pressure"]}, {"label": "Current", "values": ["Amps (A)", "Flow of electrons"]}, {"label": "Resistance", "values": ["Ohms (Ω)", "Opposition to current"]}, {"label": "Power", "values": ["Watts (W)", "Rate of energy use"]}]}, {"type": "term_set", "heading": "Two formulas", "terms": [{"term": "Ohm''s law", "short": "V = I × R, so I = V ÷ R."}, {"term": "Power", "short": "P = V × I."}, {"term": "Series resistance", "short": "Resistances add."}]}, {"type": "key_term", "term": "Worked examples", "definition": "Write the formula, plug in the numbers, check units.", "example": "12 V across 4 Ω is 3 A. 24 V at 2 A is 48 W. 10 Ω plus 20 Ω in series is 30 Ω."}, {"type": "compare", "heading": "Common components", "columns": ["Does"], "rows": [{"label": "End-of-line resistor", "values": ["Lets the panel supervise wiring for opens and shorts"]}, {"label": "Diode", "values": ["Current flows one way only"]}, {"label": "Relay", "values": ["A small signal switches another circuit"]}, {"label": "Solenoid", "values": ["A coil moves a plunger; many release actuators use one"]}], "intro": "Panels commonly run on **24 V DC** with a **secondary supply**, usually batteries. NFPA 72 sets how long they must last."}, {"type": "scenario", "prompt": "A 24 V circuit has a resistance of 8 Ω. What''s the current?", "choices": [{"id": "a", "text": "192 A"}, {"id": "b", "text": "3 A"}, {"id": "c", "text": "0.33 A"}, {"id": "d", "text": "32 A"}], "answer": "b", "why": "I = V ÷ R = 24 ÷ 8 = 3 A.", "trap": "Multiplying instead of dividing gives 192."}, {"type": "scenario", "prompt": "A notification appliance draws 0.5 A at 24 V. How much power?", "choices": [{"id": "a", "text": "48 W"}, {"id": "b", "text": "12 W"}, {"id": "c", "text": "24.5 W"}, {"id": "d", "text": "0.02 W"}], "answer": "b", "why": "P = 24 × 0.5 = 12 W."}, {"type": "callout", "variant": "tip", "text": "V = I × R and P = V × I. Write the formula before you touch the calculator."}]'::jsonb where id = 'a6a69ab3-5938-46dc-980a-cd77ddf502ef';

-- Standards, Codes, Specifications, and Listings
update lessons set content_blocks = '[{"text": "Standards, Codes, Specifications, and Listings", "type": "title", "overview": "Learn how standards, codes, specifications, and product listings differ, and the roles of NFPA, the authority having jurisdiction, designers, and manufacturers.", "examContext": "Task 1.4.3 covers the big picture. Expect questions on definitions and roles, such as who enforces a requirement and what listed means. NFPA 11 covers foam systems and is on your study list."}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Standard", "short": "A consensus document, such as NFPA 12 or 2001; enforceable once adopted or contractually required."}, {"term": "Specification", "short": "Project-specific requirements from the designer or owner."}, {"term": "Listed", "short": "Tested by a recognized lab for its intended use; valid only when installed as the manufacturer says."}, {"term": "AHJ", "short": "The authority having jurisdiction, such as a fire marshal, who enforces and approves."}]}, {"type": "diagram", "heading": "Who does what", "diagram": {"kind": "flow", "steps": [{"label": "NFPA committees", "note": "Write standards by consensus."}, {"label": "Jurisdictions", "note": "Adopt them, sometimes amended."}, {"label": "Designers", "note": "Prepare drawings and specifications."}, {"label": "Manufacturers", "note": "Provide listed equipment and manuals."}, {"label": "Installers and technicians", "note": "Build and maintain as designed."}, {"label": "AHJ", "note": "Reviews, inspects and approves."}]}}, {"type": "compare", "heading": "Shall vs. should", "columns": ["Shall", "Should"], "rows": [{"label": "Means", "values": ["Required", "Recommended"]}]}, {"type": "callout", "variant": "info", "text": "The edition your jurisdiction adopted governs on the job; exam questions follow the editions on the reference list. **NFPA 11** covers foam systems and is on the study list."}, {"type": "scenario", "prompt": "Who approves a completed special hazards installation?", "choices": [{"id": "a", "text": "The installer"}, {"id": "b", "text": "The AHJ"}, {"id": "c", "text": "The manufacturer"}, {"id": "d", "text": "NFPA"}], "answer": "b", "why": "The authority having jurisdiction."}, {"type": "scenario", "prompt": "A listed detector is installed in a way the manufacturer doesn''t allow. Is it still listed for that use?", "choices": [{"id": "a", "text": "Yes"}, {"id": "b", "text": "No; the listing only applies when installed as specified"}, {"id": "c", "text": "Only if the AHJ agrees"}, {"id": "d", "text": "Only for a year"}], "answer": "b", "why": "Listings depend on following the manufacturer''s instructions."}, {"type": "callout", "variant": "tip", "text": "Shall is mandatory, should is advice. The AHJ enforces; listings follow the manual."}]'::jsonb where id = '201ddffe-ba0b-4fef-993c-975f62c8af4b';

-- Task Area 4 Recap: System Design and Configuration
update lessons set content_blocks = '[{"text": "Task Area 4 Recap: System Design and Configuration", "type": "title", "overview": "A short review of the highest-yield facts from the three lessons in this task area.", "examContext": "This recap has no questions of its own. The Task Area 4 checkpoint draws from all three lessons, and this task area makes up roughly 8 to 18 percent of the Level I exam."}, {"type": "term_set", "heading": "Plans", "terms": [{"term": "Architectural / reflected ceiling / mechanical", "short": "Walls / ceiling items / ducts."}, {"term": "Volume", "short": "L × W × H."}, {"term": "Conflicts", "short": "RFI; don''t choose yourself."}]}, {"type": "term_set", "heading": "Electrical", "terms": [{"term": "Ohm''s law", "short": "V = I × R."}, {"term": "Power", "short": "P = V × I."}, {"term": "Series", "short": "Resistances add."}, {"term": "Panels", "short": "24 V DC with battery backup; end-of-line resistor supervises."}]}, {"type": "term_set", "heading": "Standards and roles", "terms": [{"term": "Committees, jurisdictions, AHJ", "short": "Write, adopt, enforce."}, {"term": "Listed", "short": "Lab tested, installed per the manufacturer."}, {"term": "Shall / should", "short": "Required / recommended."}, {"term": "NFPA 11", "short": "Foam systems."}]}, {"type": "scenario", "prompt": "What''s the volume of a 30 × 20 × 12 ft room?", "choices": [{"id": "a", "text": "620 cu ft"}, {"id": "b", "text": "7,200 cu ft"}, {"id": "c", "text": "720 cu ft"}, {"id": "d", "text": "6,000 cu ft"}], "answer": "b", "why": "30 × 20 × 12 = 7,200."}, {"type": "scenario", "prompt": "Two 15 Ω resistors in series total what?", "choices": [{"id": "a", "text": "7.5 Ω"}, {"id": "b", "text": "15 Ω"}, {"id": "c", "text": "30 Ω"}, {"id": "d", "text": "225 Ω"}], "answer": "c", "why": "Series resistances add."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Task Area 4 Checkpoint."}]'::jsonb where id = '07fbc29d-8572-4aa7-b2d9-279e9d49c88c';

-- Job-Site Hazards and Personal Protective Equipment
update lessons set content_blocks = '[{"text": "Job-Site Hazards and Personal Protective Equipment", "type": "title", "overview": "Learn the common hazards on a special hazards job site, the hierarchy of controls, which PPE fits which hazard, ladder rules, and which OSHA standard applies to construction and to existing facilities.", "examContext": "Task 1.5.1 is about practicing personal safety. Expect scenario questions on hazards, PPE, ladders, and OSHA. OSHA 29 CFR 1910 and 1926 are on your study list, though they are not allowed in the test center."}, {"type": "compare", "heading": "Which OSHA rules apply", "columns": ["Covers", "Example"], "rows": [{"label": "29 CFR 1926", "values": ["Construction", "Installing a new system"]}, {"label": "29 CFR 1910", "values": ["General industry", "Inspecting or maintaining an existing system"]}]}, {"type": "diagram", "heading": "Hierarchy of controls", "diagram": {"kind": "ladder", "rungs": [{"label": "Eliminate", "note": "Remove the hazard."}, {"label": "Substitute", "note": "Use something safer."}, {"label": "Engineering controls", "note": "Guards, ventilation."}, {"label": "Administrative controls", "note": "Procedures, training, signs."}, {"label": "PPE", "note": "The last line of defense.", "muted": true}], "top": "most effective", "bottom": "least"}}, {"type": "compare", "heading": "PPE for the hazard", "columns": ["Protects against"], "rows": [{"label": "Hard hat", "values": ["Falling objects, head impact"]}, {"label": "Safety glasses or goggles", "values": ["Eye injury"]}, {"label": "Gloves", "values": ["Cuts, chemicals; matched to the task"]}, {"label": "Hearing protection", "values": ["Loud equipment"]}, {"label": "Safety footwear", "values": ["Foot injury"]}, {"label": "High-visibility clothing", "values": ["Traffic and equipment"]}, {"label": "Fall protection", "values": ["Falls, where required"]}]}, {"type": "term_set", "heading": "Ladders and falls", "terms": [{"term": "Inspect", "short": "Before every use."}, {"term": "Three points of contact", "short": "While climbing."}, {"term": "4 to 1 angle", "short": "1 foot out for every 4 feet of height."}, {"term": "3 feet above the landing", "short": "Never stand on the top rung."}, {"term": "Fall protection", "short": "Generally above 4 feet in general industry, 6 feet in construction; confirm in OSHA."}]}, {"type": "scenario", "prompt": "A straight ladder reaches a landing 16 feet up. How far should its base be from the wall?", "choices": [{"id": "a", "text": "2 feet"}, {"id": "b", "text": "4 feet"}, {"id": "c", "text": "8 feet"}, {"id": "d", "text": "16 feet"}], "answer": "b", "why": "1 foot out for every 4 feet of height."}, {"type": "scenario", "prompt": "A technician inspects a clean agent system in an existing office building. Which OSHA standard applies?", "choices": [{"id": "a", "text": "1926"}, {"id": "b", "text": "1910"}, {"id": "c", "text": "Both equally"}, {"id": "d", "text": "Neither"}], "answer": "b", "why": "Maintenance in an existing facility is general industry."}, {"type": "callout", "variant": "tip", "text": "PPE is last in the hierarchy. Ladders: 4 to 1, 3 feet above, three points of contact."}]'::jsonb where id = 'ac40f134-a140-4a56-9e0d-ae6ba0380156';

-- OSHA Basics, Lockout/Tagout, and Confined Spaces
update lessons set content_blocks = '[{"text": "OSHA Basics, Lockout/Tagout, and Confined Spaces", "type": "title", "overview": "Learn the steps of lockout/tagout, basic electrical safety, and how to recognize a confined space, including why CO2 and inert gases make some spaces especially dangerous after a discharge.", "examContext": "Task 1.5.1 also covers control of hazardous energy and confined spaces. Expect scenario questions on lockout steps, who may remove a lock, and spaces where agent can accumulate."}, {"type": "diagram", "heading": "Lockout/tagout (29 CFR 1910.147)", "diagram": {"kind": "flow", "steps": [{"label": "Prepare", "note": "Identify every energy source."}, {"label": "Notify", "note": "Everyone affected."}, {"label": "Shut down"}, {"label": "Isolate"}, {"label": "Lock and tag"}, {"label": "Release stored energy"}, {"label": "Verify", "note": "Test before starting work."}]}, "caption": "Only the person who applied a lock may remove it."}, {"type": "term_set", "heading": "Electrical safety", "terms": [{"term": "Assume live", "short": "Energized until verified de-energized."}, {"term": "Insulated tools", "short": "Rated for the voltage."}, {"term": "Dry area and GFCI", "short": "Where required."}]}, {"type": "compare", "heading": "Confined space vs. permit-required", "columns": ["Confined space", "Permit-required confined space"], "rows": [{"label": "Definition", "values": ["Big enough to enter, limited entry and exit, not for continuous occupancy", "A confined space with recognized hazards"]}, {"label": "Example hazards", "values": ["None necessarily", "Hazardous atmosphere, engulfment"]}, {"label": "Entry", "values": ["Care", "A permit"]}]}, {"type": "key_term", "term": "Agent in low spaces", "definition": "CO2 is heavier than air and pools in pits and under raised floors. CO2 and inert gases displace oxygen.", "example": "After a discharge, the room air tests fine but the space under the raised floor still holds a lethal CO2 concentration."}, {"type": "scenario", "prompt": "A coworker''s lock is still on a panel at shift change and they''ve gone home. What should you do?", "choices": [{"id": "a", "text": "Cut the lock"}, {"id": "b", "text": "Follow the site procedure; only the person who applied it removes it"}, {"id": "c", "text": "Remove the tag only"}, {"id": "d", "text": "Work around it"}], "answer": "b", "why": "Lock removal belongs to whoever applied it."}, {"type": "scenario", "prompt": "After a CO2 discharge, when may someone enter the pit below the protected room?", "choices": [{"id": "a", "text": "Immediately"}, {"id": "b", "text": "After it''s ventilated and the atmosphere tested"}, {"id": "c", "text": "After 5 minutes"}, {"id": "d", "text": "If wearing a dust mask"}], "answer": "b", "why": "CO2 collects in low places and can kill."}, {"type": "callout", "variant": "tip", "text": "Verify before you work. CO2 sinks: ventilate and test before entering low spaces."}]'::jsonb where id = '7e26f8c7-bbca-4957-a55c-156c0889ce9d';

-- Hazard Communication and Safety Data Sheets
update lessons set content_blocks = '[{"text": "Hazard Communication and Safety Data Sheets", "type": "title", "overview": "Learn what OSHA''s Hazard Communication Standard requires, the elements of a chemical label, the pictograms and signal words, and what each part of a safety data sheet tells you.", "examContext": "Task 1.5.1 includes hazard communication. The OSHA Hazard Communication brief on safety data sheets is on your study list. Expect questions on SDS sections, signal words, and label elements."}, {"type": "paragraph", "text": "OSHA''s **Hazard Communication Standard** (29 CFR 1910.1200) requires labels on hazardous chemical containers, a **Safety Data Sheet** for each chemical and worker training. SDSs must be readily accessible during every shift."}, {"type": "term_set", "heading": "Label elements", "terms": [{"term": "Product identifier", "short": "What it is."}, {"term": "Signal word", "short": "Danger for more severe hazards; Warning for less severe."}, {"term": "Hazard statements", "short": "The nature of the hazard."}, {"term": "Precautionary statements", "short": "How to stay safe."}, {"term": "Pictograms", "short": "Such as a gas cylinder for gases under pressure."}, {"term": "Supplier", "short": "Who made or supplied it."}]}, {"type": "compare", "heading": "Key SDS sections (of 16)", "columns": ["Covers"], "rows": [{"label": "Section 4", "values": ["First-aid measures"]}, {"label": "Section 5", "values": ["Fire-fighting measures"]}, {"label": "Section 7", "values": ["Handling and storage"]}, {"label": "Section 8", "values": ["Exposure controls and personal protection"]}]}, {"type": "scenario", "prompt": "Which SDS section tells you what PPE to wear?", "choices": [{"id": "a", "text": "Section 4"}, {"id": "b", "text": "Section 5"}, {"id": "c", "text": "Section 7"}, {"id": "d", "text": "Section 8"}], "answer": "d", "why": "Exposure controls and personal protection."}, {"type": "scenario", "prompt": "Which signal word indicates the more severe hazard?", "choices": [{"id": "a", "text": "Warning"}, {"id": "b", "text": "Caution"}, {"id": "c", "text": "Danger"}, {"id": "d", "text": "Notice"}], "answer": "c", "why": "Danger."}, {"type": "callout", "variant": "tip", "text": "Read SDS sections 4, 7 and 8 before working on a container. Danger outranks Warning."}]'::jsonb where id = '3e40145f-b6fd-4fa7-9f00-8d8cc96333b1';

-- Handling Compressed Gas Cylinders and Basic First Aid
update lessons set content_blocks = '[{"text": "Handling Compressed Gas Cylinders and Basic First Aid", "type": "title", "overview": "Learn safe cylinder handling and storage, the hazards of agents in occupied spaces, and basic first aid for cardiac arrest, bleeding, shock, heat stroke, electric shock, and chemical eye exposure.", "examContext": "Task 1.5.1 wraps up with the hazards particular to this work. NIST S 7101.61 on compressed gas safety is on your study list, and first aid questions do appear on the exam."}, {"type": "term_set", "heading": "Cylinder handling", "terms": [{"term": "Move", "short": "On a hand truck, secured, valve cap on."}, {"term": "Never", "short": "Roll, drag or lift by the cap."}, {"term": "Store", "short": "Upright and chained or strapped."}, {"term": "Keep away", "short": "From heat and ignition."}, {"term": "Leaking or damaged", "short": "Move away, keep others clear, report."}]}, {"type": "term_set", "heading": "Agent hazards", "terms": [{"term": "CO2", "short": "Can kill at fire-suppression concentrations."}, {"term": "Inert gas", "short": "Lowers oxygen."}, {"term": "Any discharge", "short": "Loud, cold and can reduce visibility."}]}, {"type": "compare", "heading": "Basic first aid", "columns": ["Do"], "rows": [{"label": "Any emergency", "values": ["Call emergency services"]}, {"label": "Not breathing", "values": ["CPR, and an AED if available"]}, {"label": "Severe bleeding", "values": ["Firm direct pressure"]}, {"label": "Shock: pale, cool, clammy, rapid pulse", "values": ["Lay them down and keep them warm"]}, {"label": "Heat stroke: hot skin, confusion", "values": ["Call for help and cool them quickly"]}, {"label": "Electric shock", "values": ["Power off before touching them"]}, {"label": "Chemical in the eye", "values": ["Flush with water at least 15 minutes"]}]}, {"type": "scenario", "prompt": "A coworker is still holding a live conductor and can''t let go. What''s the first action?", "choices": [{"id": "a", "text": "Pull them away"}, {"id": "b", "text": "Turn off the power"}, {"id": "c", "text": "Start CPR"}, {"id": "d", "text": "Pour water on them"}], "answer": "b", "why": "Touching them first makes you a second victim."}, {"type": "scenario", "prompt": "How long should an eye be flushed after a chemical splash?", "choices": [{"id": "a", "text": "1 minute"}, {"id": "b", "text": "5 minutes"}, {"id": "c", "text": "At least 15 minutes"}, {"id": "d", "text": "Until it stops stinging"}], "answer": "c", "why": "At least 15 minutes."}, {"type": "callout", "variant": "tip", "text": "Cylinders: hand truck, cap on, never lift by the cap. Electric shock: power off before touching."}]'::jsonb where id = '0de192e6-f106-43ee-b030-2f5e7a12ce64';

-- Task Area 5 Recap: Safety
update lessons set content_blocks = '[{"text": "Task Area 5 Recap: Safety", "type": "title", "overview": "A short review of the highest-yield facts from the four lessons in this task area.", "examContext": "This recap has no questions of its own. The Task Area 5 checkpoint draws from all four lessons, and this task area makes up roughly 10 to 20 percent of the Level I exam."}, {"type": "term_set", "heading": "Rules and controls", "terms": [{"term": "OSHA 1926 / 1910", "short": "Construction / general industry."}, {"term": "Hierarchy", "short": "PPE is last."}, {"term": "Ladders", "short": "4 to 1, 3 feet above, three points of contact."}, {"term": "Fall protection", "short": "4 feet general industry, 6 feet construction."}]}, {"type": "term_set", "heading": "Energy and spaces", "terms": [{"term": "LOTO", "short": "Isolate, lock, tag, release stored energy, verify."}, {"term": "Locks", "short": "Only whoever applied it removes it."}, {"term": "Circuits", "short": "Energized until verified dead."}, {"term": "CO2", "short": "Heavier than air; ventilate and test before entering."}]}, {"type": "term_set", "heading": "Chemicals, cylinders, first aid", "terms": [{"term": "SDS", "short": "16 sections; 4 is first aid, 8 is PPE."}, {"term": "Danger / Warning", "short": "More severe / less severe."}, {"term": "Cylinders", "short": "Hand truck, cap on."}, {"term": "First aid", "short": "CPR, pressure, warm for shock, cool for heat stroke, power off, flush 15 minutes."}]}, {"type": "scenario", "prompt": "Which OSHA standard covers installing a new system?", "choices": [{"id": "a", "text": "1910"}, {"id": "b", "text": "1926"}, {"id": "c", "text": "1910.1200"}, {"id": "d", "text": "1910.147"}], "answer": "b", "why": "Construction."}, {"type": "scenario", "prompt": "Treat shock by doing what?", "choices": [{"id": "a", "text": "Cooling them"}, {"id": "b", "text": "Laying them down and keeping them warm"}, {"id": "c", "text": "Giving water"}, {"id": "d", "text": "Walking them around"}], "answer": "b", "why": "Lay down, keep warm."}, {"type": "scenario", "prompt": "What''s the last step of lockout/tagout before work?", "choices": [{"id": "a", "text": "Notify"}, {"id": "b", "text": "Verify isolation"}, {"id": "c", "text": "Apply the tag"}, {"id": "d", "text": "Shut down"}], "answer": "b", "why": "Test before you touch."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Task Area 5 Checkpoint, then the full practice exams."}]'::jsonb where id = '0692bb12-9a2c-4bd5-a98d-0faa8f0aeaaa';
